import { useState, useEffect } from 'react';
import { Outlet, useNavigate, Link, Routes, Route } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

// Import your admin pages
import Home from './Home';
import Students from './Students';
import Courses from './Courses';
import Questions from './Questions';

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // Set active tab based on URL
  useEffect(() => {
    const path = window.location.pathname;
    if (path === '/admin') setActiveTab('dashboard');
    else if (path === '/admin/students') setActiveTab('students');
    else if (path === '/admin/courses') setActiveTab('courses');
    else if (path === '/admin/questions') setActiveTab('questions');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  // Close sidebar when clicking outside (mobile)
  useEffect(() => {
    const handleClickOutside = () => {
      if (window.innerWidth < 768) {
        setSidebarOpen(false);
      }
    };
    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  return (
    <div className="d-flex min-vh-100 bg-light">
      {/* Sidebar - Hidden on mobile by default */}
      <nav 
        className={`bg-dark text-white d-md-block d-none position-fixed vh-100`}
        style={{ width: '250px', zIndex: 1000 }}
      >
        <div className="p-3">
          <img 
            src="https://cdn-icons-png.flaticon.com/512/2972/2972185.png" 
            alt="Quiz Logo" 
            className="img-fluid"
            style={{ maxHeight: '60px' }}
          />
        </div>
        <ul className="nav flex-column px-3">
          {[
            { id: 'dashboard', label: 'Home', icon: 'fa-home', path: '/admin' },
            { id: 'students', label: 'Students', icon: 'fa-user', path: '/admin/students' },
            { id: 'courses', label: 'Courses', icon: 'fa-book', path: '/admin/courses' },
            { id: 'questions', label: 'Questions', icon: 'fa-question', path: '/admin/questions' }
          ].map(item => (
            <li key={item.id} className="nav-item">
              <Link 
                to={item.path}
                onClick={() => setActiveTab(item.id)}
                className={`nav-link text-white d-flex align-items-center py-3 ${activeTab === item.id ? 'bg-primary' : 'border-bottom border-secondary'}`}
              >
                <i className={`fas ${item.icon} me-3`}></i>
                <span>{item.label}</span>
              </Link>
            </li>
          ))}
        </ul>
      </nav>

      {/* Mobile sidebar toggle button */}
      <div className="d-md-none d-block p-3 bg-dark text-white" style={{ width: '100%' }}>
        <div className="d-flex justify-content-between align-items-center">
          <button 
            className="btn btn-outline-light me-2"
            onClick={(e) => {
              e.stopPropagation();
              setSidebarOpen(!sidebarOpen);
            }}
          >
            <i className="fas fa-bars"></i>
          </button>
          <h5 className="mb-0">Admin Panel</h5>
          <div></div> {/* Spacer for alignment */}
        </div>
        
        {/* Mobile sidebar dropdown */}
        {sidebarOpen && (
          <div 
            className="position-absolute bg-dark text-white w-100 mt-2"
            style={{ zIndex: 1001 }}
            onClick={(e) => e.stopPropagation()}
          >
            <ul className="nav flex-column">
              {[
                { id: 'dashboard', label: 'Home', icon: 'fa-home', path: '/admin' },
                { id: 'students', label: 'Students', icon: 'fa-user', path: '/admin/students' },
                { id: 'courses', label: 'Courses', icon: 'fa-book', path: '/admin/courses' },
                { id: 'questions', label: 'Questions', icon: 'fa-question', path: '/admin/questions' }
              ].map(item => (
                <li key={item.id} className="nav-item">
                  <Link 
                    to={item.path}
                    onClick={() => {
                      setActiveTab(item.id);
                      setSidebarOpen(false);
                    }}
                    className={`nav-link text-white d-flex align-items-center py-2 ${activeTab === item.id ? 'bg-primary' : ''}`}
                  >
                    <i className={`fas ${item.icon} me-3`}></i>
                    <span>{item.label}</span>
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>

      {/* Main Content */}
      <div className="flex-grow-1" style={{ marginLeft: window.innerWidth >= 768 ? '250px' : '0' }}>
        <header className="bg-white shadow-sm p-3 mb-4">
          <div className="d-flex justify-content-between align-items-center">
            <h2 className="mb-0">Admin Dashboard</h2>
            <button 
              onClick={handleLogout}
              className="btn btn-danger btn-sm"
            >
              Logout
            </button>
          </div>
        </header>

        {/* Nested Routes */}
        <div className="container-fluid px-4">
          <Routes>
            <Route index element={<Home />} />
            <Route path="students" element={<Students />} />
            <Route path="courses" element={<Courses />} />
            <Route path="questions" element={<Questions />} />
          </Routes>
        </div>
      </div>
    </div>
  );
}
